package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Save the settings the input sets: each dated one recorded from its from-date (not given: the sheet's today),
 *  keeping the values already recorded (one from that same date is replaced); the policy date and the period
 *  numbering from as they are. */
public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input, SettingRepository repository,
            Out<Settings> settings) {
        String id = sheetId.trim();
        LocalDate today = repository.today(id);
        if (input.setsClerkLimit()) {
            repository.setDated(id, "clerk-limit", text(input.clerkLimit()), from(input, "clerk-limit", today));
        }
        if (input.floor() != null) {
            repository.setDated(id, "floor", text(input.floor()), from(input, "floor", today));
        }
        if (input.terms() != null) {
            repository.setDated(id, "terms", String.valueOf(input.terms()), from(input, "terms", today));
        }
        input.gradeTerms().forEach((grade, days) -> repository.setDated(id, "terms-" + grade,
                days != null ? String.valueOf(days) : null, from(input, "terms-" + grade, today)));
        if (input.latePct() != null) {
            repository.setDated(id, "late-pct", text(input.latePct()), from(input, "late-pct", today));
        }
        if (input.setsPolicyDate()) {
            repository.setPolicyDate(id, input.policyDate());
        }
        if (input.setsPeriodNumberingFrom()) {
            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
        }
        if (input.setsCap()) {
            repository.setDated(id, "cap", text(input.cap()), from(input, "cap", today));
        }
        settings.set(repository.of(id));
    }

    private static LocalDate from(SettingsInput input, String key, LocalDate today) {
        LocalDate from = input.from().get(key);
        return from != null ? from : today != null ? today : LocalDate.of(1, 1, 1);
    }

    private static String text(BigDecimal value) {
        return value != null ? value.toPlainString() : null;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;

/** A sheet's dated settings: by key (floor, late-pct, terms, terms-A/B/C, clerk-limit, cap), each value recorded
 *  by its from-date (null: blank). The value in force on a date is the one with the latest from-date on or before
 *  it; before every from-date the sheet's starting value applies. */
public record SettingHistory(Map<String, NavigableMap<LocalDate, String>> values) {

    /** The keys of the settings that are dated. */
    public static final List<String> KEYS = List.of("clerk-limit", "floor", "terms", "terms-A",
            "terms-B", "terms-C", "late-pct", "cap");

    /** The key's values, oldest from-date first (empty when it has none). */
    public NavigableMap<LocalDate, String> of(String key) {
        return values.getOrDefault(key, new TreeMap<>());
    }

    /** The key's value in force on the date (null date: its latest); null when none is (its starting value applies). */
    private Map.Entry<LocalDate, String> entryOn(String key, LocalDate date) {
        NavigableMap<LocalDate, String> theirs = of(key);
        return date == null ? theirs.lastEntry() : theirs.floorEntry(date);
    }

    /** The floor in force on the date: two decimals. */
    public BigDecimal floorOn(LocalDate date) {
        var e = entryOn("floor", date);
        return e != null && e.getValue() != null ? new BigDecimal(e.getValue()).setScale(2) : SettingRepository.DEFAULT_FLOOR;
    }

    /** The late percent in force on the date: two decimals. */
    public BigDecimal latePctOn(LocalDate date) {
        var e = entryOn("late-pct", date);
        return e != null && e.getValue() != null ? new BigDecimal(e.getValue()).setScale(2) : SettingRepository.DEFAULT_LATE_PCT;
    }

    /** The sheet's terms in force on the date, in days. */
    public int termsOn(LocalDate date) {
        var e = entryOn("terms", date);
        return e != null && e.getValue() != null ? Integer.parseInt(e.getValue()) : SettingRepository.DEFAULT_TERMS;
    }

    /** The grade's own terms in force on the date, in days; null when it has none then (it uses the sheet's). */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        var e = entryOn("terms-" + grade, date);
        return e != null && e.getValue() != null ? Integer.valueOf(e.getValue()) : null;
    }

    /** The terms a claim of the grade dated on the date gets: the grade's own then, else the sheet's then. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = grade != null ? gradeTermsOn(grade, date) : null;
        return own != null ? own : termsOn(date);
    }

    /** The clerk limit in force on the date: two decimals, or null when there is none. */
    public BigDecimal clerkLimitOn(LocalDate date) {
        return amountOn("clerk-limit", date);
    }

    /** The cap in force on the date: two decimals, or null when there is none. */
    public BigDecimal capOn(LocalDate date) {
        return amountOn("cap", date);
    }

    private BigDecimal amountOn(String key, LocalDate date) {
        var e = entryOn(key, date);
        return e != null && e.getValue() != null ? new BigDecimal(e.getValue()).setScale(2) : null;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The sheet's settings: the dated ones (see SettingHistory) one value per key and from-date, the policy date and
 *  the period numbering from (not dated) on the sheet's row. */
@Repository
public class SettingRepository {

    /** The floor of a sheet before any is in force. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms of a sheet before any are in force. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent of a sheet before any is in force. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings in force on its today. */
    public Settings of(String sheetId) {
        SettingHistory history = history(sheetId);
        LocalDate today = today(sheetId);
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        for (String grade : ValidateSettings.GRADES) {
            Integer days = history.gradeTermsOn(grade, today);
            if (days != null) {
                gradeTerms.put(grade, days);
            }
        }
        return new Settings(sheetId, history.clerkLimitOn(today), history.floorOn(today), history.termsOn(today),
                history.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId), gradeTerms,
                history.capOn(today), history);
    }

    /** Every value of the sheet's dated settings, by key and from-date. */
    public SettingHistory history(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> values = new HashMap<>();
        jdbc.query("SELECT setting_key, from_date, val FROM setting_value WHERE sheet_id = ?", rs -> {
            values.computeIfAbsent(rs.getString(1), k -> new TreeMap<>())
                    .put(rs.getObject(2, LocalDate.class), rs.getString(3));
        }, sheetId);
        return new SettingHistory(values);
    }

    /** Record the dated setting's value (null: blank) from the from-date, replacing any it had from that date. */
    public void setDated(String sheetId, String key, String value, LocalDate from) {
        jdbc.update("DELETE FROM setting_value WHERE sheet_id = ? AND setting_key = ? AND from_date = ?",
                sheetId, key, from);
        jdbc.update("INSERT INTO setting_value (sheet_id, setting_key, from_date, val) VALUES (?, ?, ?, ?)",
                sheetId, key, from, value);
    }

    /** The sheet's clerk limit in force on its today: two decimals, or null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return history(sheetId).clerkLimitOn(today(sheetId));
    }

    /** The sheet's cap in force on its today: two decimals, or null when there is none; a person's due-total is at
     *  most it. */
    public BigDecimal cap(String sheetId) {
        return history(sheetId).capOn(today(sheetId));
    }

    /** The sheet's floor by date: a claim's live due is at least the floor in force on its date. */
    public DatedAmount floor(String sheetId) {
        return history(sheetId)::floorOn;
    }

    /** The sheet's late percent by date: an overdue claim gains the one in force on its date, of its figure, every
     *  full 30 days. */
    public DatedAmount latePct(String sheetId) {
        return history(sheetId)::latePctOn;
    }

    /** The terms in days a claim of the grade dated on the date gets: the grade's own in force then, else the
     *  sheet's in force then. */
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return history(sheetId).termsFor(grade, date);
    }

    /** The sheet's policy date: null when blank (the sheet's today is the policy date then). */
    public LocalDate policyDate(String sheetId) {
        return jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPolicyDate(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's period numbering from: null when blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }

    public void setPeriodNumberingFrom(String sheetId, LocalDate date) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", date, sheetId);
    }

    /** The sheet's today: dated settings are shown, and saved by default, as of it. */
    public LocalDate today(String sheetId) {
        return jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
    }
}
