import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useClaims } from '../claims/claims';
import type { Late } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';

/** The sheet's settings: the clerk limit with two decimals ('' when there is none) and the floor with two
 *  decimals (a claim's live due is at least it), and the terms in days (a claim's due-by is its date plus them), and
 *  the late percent with two decimals (an overdue claim gains it, of its figure, every full 30 days), and the
 *  policy date (yyyy-mm-dd; '' when blank: the sheet's today) a claim's live figures round by, and the period numbering from (yyyy-mm-dd; '' when off: on or after it, by
 *  the sheet's today, a claim opened is numbered within its period), and each grade's own terms in days ('' when the
 *  grade has none: it uses the sheet's terms), and the cap with two decimals ('' when there is none: a person's
 *  due-total is at most it). A claim's due-by is fixed when it is created. Each is the value in force on the sheet's
 *  today; `dated` holds every value recorded for the settings that carry a figure, by key (clerk-limit, floor, terms,
 *  terms-A/B/C, late-pct, cap), oldest from-date first. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string;
  periodNumberingFrom: string; gradeTerms: Record<string, string>; cap: string; dated?: Record<string, Dated[]> };

/** A dated setting's value ('' when blank) in force from its from-date (yyyy-mm-dd). */
export type Dated = { from: string; value: string };

/** A dated figure as it applies to a date (yyyy-mm-dd): the value in force on it. */
export type DatedValue = (date: string) => string;

/** The value of a dated setting in force on a date: the one with the latest from-date on or before it, else the
 *  sheet's starting value. */
export function valueOn(values: Dated[] | undefined, start: string, date: string): string {
  let found: Dated | undefined;
  for (const v of values ?? []) {
    if (v.from <= date && (!found || found.from < v.from)) found = v;
  }
  return found ? found.value : start;
}

/** The grades that may have terms of their own. */
export const GRADES = ['A', 'B', 'C'] as const;

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days. */
export const DEFAULT_TERMS = '14';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's settings as they are now. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The sheet's floor by date: a claim's live due is at least the one in force on its date (the starting floor
 *  while the settings load). */
export function useFloor(sheetId: string): DatedValue {
  const dated = useSettings(sheetId).data?.dated?.floor;
  return useMemo(() => (date: string) => valueOn(dated, DEFAULT_FLOOR, date), [dated]);
}

/** The sheet's cap in force ('' when there is none, or while the settings load). */
export function useCap(sheetId: string): string {
  return useSettings(sheetId).data?.cap ?? '';
}

/** The sheet's terms in force, in days (the starting terms while the settings load). */
export function useTerms(sheetId: string): number {
  return Number(useSettings(sheetId).data?.terms ?? DEFAULT_TERMS);
}

/** What the late charge follows now: the late percent by date (a claim gains the one in force on its date) and the sheet's today; and how claims round:
 *  the policy date in force (blank: the sheet's today) and the dates of the sheet's numbered claims. */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId);
  const claims = useClaims(sheetId).data;
  const numbered = useMemo(
    () => new Map((claims ?? []).filter((c) => c.number !== null).map((c) => [c.number as string, c.date])),
    [claims],
  );
  const dated = settings?.dated?.['late-pct'];
  const pct = useMemo(() => (date: string) => valueOn(dated, DEFAULT_LATE_PCT, date), [dated]);
  return { pct, today,
    policy: settings?.policyDate || today, numbered };
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { DEFAULT_FLOOR, DEFAULT_LATE_PCT, DEFAULT_TERMS, GRADES, settingsKey, useSettings, type Settings } from './settings';

const LIMIT = /^\d+(\.\d{1,2})?$/;
const DAYS = /^\d{1,4}$/;
const PCT = /^\d{1,3}(\.\d{1,2})?$/;
const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The settings that carry a figure, and so are saved from a from-date. */
const DATED = ['clerk-limit', 'floor', 'terms', ...GRADES.map((grade) => `terms-${grade}`), 'late-pct', 'cap'];

/** The settings a save changes: only those typed into since the last save are sent (and recorded). */
type Changes = { clerkLimit?: string; floor?: string; terms?: string; latePct?: string; policyDate?: string;
  periodNumberingFrom?: string; gradeTerms?: Record<string, string>; cap?: string; from?: Record<string, string> };

/** The sheet's settings — the clerk limit and the floor in force, and the form that saves them (a blank clerk
 *  limit: no limit). A clerk may settle only claims whose due is at or below the limit; the server enforces it.
 *  A claim's live due is at least the floor; its due-by is its date plus the terms; once overdue it gains the late
 *  percent of its figure for every full 30 days. A claim dated before the policy date (blank: the sheet's today)
 *  rounds its live figures half up, one on or after it half to even. While the period numbering from is a date
 *  on or before the sheet's today, a claim opened is numbered within its period (<period>-<n>, X-<n> in none).
 *  A grade may have terms of its own (blank: the sheet's terms); a claim's due-by is fixed when it is created, from
 *  the terms of its person's grade on its date. A person's due-total is at most the cap (blank: none).
 *  The settings that carry a figure are dated: each is saved from a from-date (blank: the sheet's today), keeping
 *  the values already recorded; a claim takes the floor, late percent and terms in force on its date. What is shown
 *  is the value in force on the sheet's today. Typing a from-date alone saves the value shown from it. */
function SettingsSection({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const settings = useSettings(sheetId);
  const currentLimit = settings.data?.clerkLimit ?? '';
  const currentFloor = settings.data?.floor ?? DEFAULT_FLOOR;
  const currentTerms = settings.data?.terms ?? DEFAULT_TERMS;
  const currentLatePct = settings.data?.latePct ?? DEFAULT_LATE_PCT;
  const currentPolicyDate = settings.data?.policyDate ?? '';
  const currentNumberingFrom = settings.data?.periodNumberingFrom ?? '';
  const currentCap = settings.data?.cap ?? '';
  // null: not typed in since the last save, so the field shows the setting in force.
  const [typedLimit, setTypedLimit] = useState<string | null>(null);
  const [typedFloor, setTypedFloor] = useState<string | null>(null);
  const [typedTerms, setTypedTerms] = useState<string | null>(null);
  const [typedLatePct, setTypedLatePct] = useState<string | null>(null);
  const [typedPolicyDate, setTypedPolicyDate] = useState<string | null>(null);
  const [typedNumberingFrom, setTypedNumberingFrom] = useState<string | null>(null);
  const [typedCap, setTypedCap] = useState<string | null>(null);
  const currentGradeTerms = (grade: string) => settings.data?.gradeTerms?.[grade] ?? '';
  const [typedGradeTerms, setTypedGradeTerms] = useState<Record<string, string>>({});
  // From-dates typed in since the last save, by dated setting key.
  const [typedFrom, setTypedFrom] = useState<Record<string, string>>({});
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (changes: Changes) =>
      putJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, { user, ...changes }),
    onSuccess: (saved) => {
      queryClient.setQueryData(settingsKey(sheetId), saved);
      setTypedLimit(null);
      setTypedFloor(null);
      setTypedTerms(null);
      setTypedLatePct(null);
      setTypedPolicyDate(null);
      setTypedNumberingFrom(null);
      setTypedCap(null);
      setTypedGradeTerms({});
      setTypedFrom({});
    },
    onError: (e) =>
      setError(e instanceof HttpError && e.body
        ? e.body
        : 'Could not save the settings: the clerk limit and floor must be amounts with up to two decimals, the terms whole days, the late percent a percent, the policy date and period numbering from dates or blank.'),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
